import React from "react";
import { useNavigate } from "react-router-dom";

export default function NotFoundPage() {
  const navigate = useNavigate();
  return (
    <div style={{ minHeight: "calc(100vh - var(--nav-h))", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center", padding: 40 }}>
      <div style={{ fontFamily: "'DM Serif Display',serif", fontSize: 90, color: "var(--border)", lineHeight: 1, marginBottom: 8 }}>404</div>
      <h2 className="h2" style={{ marginBottom: 10 }}>Page not found</h2>
      <p style={{ color: "var(--muted)", fontSize: 15, marginBottom: 28, maxWidth: 360 }}>The page you're looking for doesn't exist or has been moved.</p>
      <div style={{ display: "flex", gap: 12 }}>
        <button className="btn btn-dark" onClick={() => navigate("/")}>← Go Home</button>
        <button className="btn btn-out"  onClick={() => navigate("/explore")}>Explore Rooms</button>
      </div>
    </div>
  );
}
